import React, { useState } from "react";
import { motion } from "framer-motion";
import {
  User,
  Droplets,
  Calendar,
  MapPin,
  Phone,
  Heart,
  Check,
  X,
  Clock,
  Award,
  Activity,
} from "lucide-react";
import Notifications from "../components/common/Notifications";

const DonorDashboard = () => {
  const [availability, setAvailability] = useState(true);
  const [activeTab, setActiveTab] = useState("profile");
  const [notifications, setNotifications] = useState([
    {
      id: 1,
      type: "emergency",
      message: "Emergency request for O+ blood near you",
      time: "5 min ago",
      urgent: true,
    },
    {
      id: 2,
      type: "reminder",
      message: "Your next donation is due in 2 weeks",
      time: "1 hour ago",
      urgent: false,
    },
  ]);

  // Mock data for donor profile
  const donorProfile = {
    name: "Sarah Johnson",
    bloodType: "O+",
    lastDonation: "2024-01-15",
    nextEligible: "2024-04-15",
    donationsCount: 12,
    status: "eligible",
    location: "Manhattan, NY",
    contact: "+1 (555) 123-4567",
  };

  // Mock data for donation history
  const donationHistory = [
    {
      id: 1,
      date: "2024-01-15",
      location: "City General Hospital",
      volume: "450ml",
      status: "completed",
    },
    {
      id: 2,
      date: "2023-10-22",
      location: "St. Mary Medical Center",
      volume: "450ml",
      status: "completed",
    },
    {
      id: 3,
      date: "2023-07-30",
      location: "Regional Blood Bank",
      volume: "450ml",
      status: "completed",
    },
    {
      id: 4,
      date: "2023-04-18",
      location: "City General Hospital",
      volume: "450ml",
      status: "completed",
    },
  ];

  // Mock data for nearby requests
  const nearbyRequests = [
    {
      id: 1,
      patient: "John Doe",
      bloodType: "O+",
      hospital: "City General Hospital",
      distance: "2.5 km",
      urgency: "high",
      time: "2 min ago",
    },
    {
      id: 2,
      patient: "Jane Smith",
      bloodType: "O+",
      hospital: "St. Mary Medical Center",
      distance: "4.2 km",
      urgency: "medium",
      time: "15 min ago",
    },
  ];

  const getStatusColor = (status) => {
    switch (status) {
      case "eligible":
        return "text-green-400 bg-green-500/20 border border-green-500/30";
      case "ineligible":
        return "text-red-400 bg-red-500/20 border border-red-500/30";
      case "pending":
        return "text-yellow-400 bg-yellow-500/20 border border-yellow-500/30";
      case "completed":
        return "text-blue-400 bg-blue-500/20 border border-blue-500/30";
      default:
        return "text-gray-400 bg-gray-500/20 border border-gray-500/30";
    }
  };

  const toggleAvailability = () => {
    setAvailability(!availability);
  };

  const dismissNotification = (id) => {
    setNotifications(
      notifications.filter((notification) => notification.id !== id)
    );
  };

  const containerVariants = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        staggerChildren: 0.1,
      },
    },
  };

  const itemVariants = {
    hidden: { y: 20, opacity: 0 },
    visible: {
      y: 0,
      opacity: 1,
      transition: { duration: 0.5 },
    },
  };

  return (
    <div className="min-h-screen bg-gray-900">
      {/* Notifications */}
      <div className="fixed top-4 right-4 z-50">
        <Notifications />
      </div>

      {/* Header */}
      <motion.header
        initial={{ y: -100, opacity: 0 }}
        animate={{ y: 0, opacity: 1 }}
        className="glass-card m-6 rounded-2xl p-6 shadow-xl"
      >
        <div className="flex flex-col md:flex-row md:items-center md:justify-between">
          <div>
            <h1 className="text-3xl font-bold text-white">Donor Dashboard</h1>
            <p className="text-gray-300">Help save lives by donating blood</p>
          </div>
          <div className="mt-4 md:mt-0 flex items-center space-x-4">
            <div className="text-right">
              <p className="text-white font-medium">{donorProfile.name}</p>
              <p className="text-gray-400 text-sm">{donorProfile.location}</p>
            </div>
            <div className="w-12 h-12 bg-red-500 rounded-full flex items-center justify-center">
              <User className="w-6 h-6 text-white" />
            </div>
          </div>
        </div>
      </motion.header>

      {/* Availability Toggle */}
      <motion.div
        initial={{ y: -50, opacity: 0 }}
        animate={{ y: 0, opacity: 1 }}
        transition={{ delay: 0.1 }}
        className="mx-6 mb-6"
      >
        <div className="glass-card p-6 rounded-2xl flex flex-col md:flex-row md:items-center md:justify-between">
          <div className="flex items-center mb-4 md:mb-0">
            <div className="mr-4">
              <div className="w-16 h-16 bg-red-500 rounded-full flex items-center justify-center">
                <Droplets className="w-8 h-8 text-white" />
              </div>
            </div>
            <div>
              <h3 className="text-xl font-bold text-white">
                Blood Type:{" "}
                <span className="text-red-400">{donorProfile.bloodType}</span>
              </h3>
              <p className="text-gray-300">Universal donor</p>
            </div>
          </div>
          <div className="flex items-center">
            <span
              className={`mr-3 font-medium ${
                availability ? "text-green-400" : "text-gray-400"
              }`}
            >
              {availability ? "Available" : "Unavailable"}
            </span>
            <motion.button
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
              onClick={toggleAvailability}
              className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors ${
                availability ? "bg-red-500" : "bg-gray-600"
              }`}
            >
              <motion.span
                animate={{ x: availability ? 24 : 4 }}
                transition={{ type: "spring", stiffness: 300, damping: 20 }}
                className="inline-block h-4 w-4 transform rounded-full bg-white"
              />
            </motion.button>
          </div>
        </div>
      </motion.div>

      {/* Notifications */}
      {notifications.length > 0 && (
        <motion.div
          initial={{ y: -50, opacity: 0 }}
          animate={{ y: 0, opacity: 1 }}
          transition={{ delay: 0.2 }}
          className="mx-6 mb-6 space-y-3"
        >
          {notifications.map((notification) => (
            <motion.div
              key={notification.id}
              initial={{ opacity: 0, x: -20 }}
              animate={{ opacity: 1, x: 0 }}
              className={`glass-card p-4 rounded-xl flex items-center justify-between ${
                notification.urgent
                  ? "border-l-4 border-red-500"
                  : "border-l-4 border-blue-500"
              }`}
            >
              <div className="flex items-center">
                {notification.urgent ? (
                  <div className="w-10 h-10 bg-red-500/20 rounded-full flex items-center justify-center mr-3">
                    <Heart className="w-5 h-5 text-red-400" />
                  </div>
                ) : (
                  <div className="w-10 h-10 bg-blue-500/20 rounded-full flex items-center justify-center mr-3">
                    <Clock className="w-5 h-5 text-blue-400" />
                  </div>
                )}
                <div>
                  <p className="text-white font-medium">
                    {notification.message}
                  </p>
                  <p className="text-gray-400 text-sm">{notification.time}</p>
                </div>
              </div>
              <button
                onClick={() => dismissNotification(notification.id)}
                className="text-gray-400 hover:text-white"
              >
                <X className="w-5 h-5" />
              </button>
            </motion.div>
          ))}
        </motion.div>
      )}

      {/* Navigation Tabs */}
      <motion.nav
        initial={{ y: -50, opacity: 0 }}
        animate={{ y: 0, opacity: 1 }}
        transition={{ delay: 0.3 }}
        className="mx-6 mb-6"
      >
        <div className="flex space-x-1 glass-card p-2 rounded-2xl">
          {["profile", "requests", "history"].map((tab) => (
            <button
              key={tab}
              onClick={() => setActiveTab(tab)}
              className={`flex-1 py-3 px-4 rounded-xl font-medium transition-all duration-200 ${
                activeTab === tab
                  ? "bg-red-600 text-white shadow-lg"
                  : "text-gray-300 hover:text-white hover:bg-white/10"
              }`}
            >
              {tab.charAt(0).toUpperCase() + tab.slice(1)}
            </button>
          ))}
        </div>
      </motion.nav>

      <motion.main
        variants={containerVariants}
        initial="hidden"
        animate="visible"
        className="mx-6 mb-6"
      >
        {/* Profile Tab */}
        {activeTab === "profile" && (
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            {/* Profile Card */}
            <motion.div
              variants={itemVariants}
              className="lg:col-span-2 glass-card p-6 rounded-2xl"
            >
              <h2 className="text-2xl font-bold text-white mb-6">My Profile</h2>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-4">
                  <div>
                    <p className="text-gray-400 text-sm">Full Name</p>
                    <p className="text-white font-medium">
                      {donorProfile.name}
                    </p>
                  </div>
                  <div>
                    <p className="text-gray-400 text-sm">Blood Type</p>
                    <p className="text-red-400 font-medium text-xl">
                      {donorProfile.bloodType}
                    </p>
                  </div>
                  <div>
                    <p className="text-gray-400 text-sm">Last Donation</p>
                    <p className="text-white font-medium">
                      {donorProfile.lastDonation}
                    </p>
                  </div>
                  <div>
                    <p className="text-gray-400 text-sm">Next Eligible Date</p>
                    <p className="text-white font-medium">
                      {donorProfile.nextEligible}
                    </p>
                  </div>
                </div>
                <div className="space-y-4">
                  <div>
                    <p className="text-gray-400 text-sm">Location</p>
                    <p className="text-white font-medium">
                      {donorProfile.location}
                    </p>
                  </div>
                  <div>
                    <p className="text-gray-400 text-sm">Contact</p>
                    <p className="text-white font-medium">
                      {donorProfile.contact}
                    </p>
                  </div>
                  <div>
                    <p className="text-gray-400 text-sm">Total Donations</p>
                    <p className="text-white font-medium">
                      {donorProfile.donationsCount}
                    </p>
                  </div>
                  <div>
                    <p className="text-gray-400 text-sm">Status</p>
                    <span
                      className={`px-3 py-1 rounded-full text-sm font-medium ${getStatusColor(
                        donorProfile.status
                      )}`}
                    >
                      {donorProfile.status.charAt(0).toUpperCase() +
                        donorProfile.status.slice(1)}
                    </span>
                  </div>
                </div>
              </div>
            </motion.div>

            {/* Stats Card */}
            <motion.div
              variants={itemVariants}
              className="glass-card p-6 rounded-2xl"
            >
              <h3 className="text-xl font-bold text-white mb-6">
                Donation Stats
              </h3>
              <div className="space-y-6">
                <div className="text-center p-4 bg-gradient-to-r from-red-500/10 to-red-600/10 rounded-xl">
                  <Award className="w-8 h-8 text-red-400 mx-auto mb-2" />
                  <p className="text-2xl font-bold text-white">
                    {donorProfile.donationsCount}
                  </p>
                  <p className="text-gray-300 text-sm">Total Donations</p>
                </div>
                <div className="text-center p-4 bg-gradient-to-r from-green-500/10 to-green-600/10 rounded-xl">
                  <Activity className="w-8 h-8 text-green-400 mx-auto mb-2" />
                  <p className="text-2xl font-bold text-white">12L+</p>
                  <p className="text-gray-300 text-sm">Blood Donated</p>
                </div>
                <div className="text-center p-4 bg-gradient-to-r from-blue-500/10 to-blue-600/10 rounded-xl">
                  <Heart className="w-8 h-8 text-blue-400 mx-auto mb-2" />
                  <p className="text-2xl font-bold text-white">48+</p>
                  <p className="text-gray-300 text-sm">Lives Saved</p>
                </div>
              </div>
            </motion.div>
          </div>
        )}

        {/* Requests Tab */}
        {activeTab === "requests" && (
          <motion.div variants={itemVariants}>
            <h2 className="text-2xl font-bold text-white mb-6">
              Nearby Requests
            </h2>
            <div className="space-y-4">
              {nearbyRequests.map((request, index) => (
                <motion.div
                  key={request.id}
                  initial={{ opacity: 0, x: -20 }}
                  animate={{ opacity: 1, x: 0 }}
                  transition={{ delay: index * 0.1 }}
                  className="p-6 glass-card rounded-2xl"
                >
                  <div className="flex flex-col md:flex-row md:items-center md:justify-between">
                    <div className="flex-1">
                      <div className="flex items-center mb-2">
                        <span
                          className={`px-3 py-1 rounded-full text-xs font-medium ${
                            request.urgency === "high"
                              ? "text-red-400 bg-red-500/20"
                              : "text-yellow-400 bg-yellow-500/20"
                          }`}
                        >
                          {request.urgency.charAt(0).toUpperCase() +
                            request.urgency.slice(1)}{" "}
                          Priority
                        </span>
                        <span className="ml-3 px-3 py-1 rounded-full text-xs font-medium text-red-400 bg-red-500/20">
                          {request.bloodType}
                        </span>
                      </div>
                      <h3 className="text-lg font-semibold text-white">
                        {request.patient}
                      </h3>
                      <div className="flex items-center text-gray-300 mt-2">
                        <MapPin className="w-4 h-4 mr-2" />
                        <span>{request.hospital}</span>
                        <span className="mx-2">•</span>
                        <span>{request.distance}</span>
                        <span className="mx-2">•</span>
                        <span>{request.time}</span>
                      </div>
                    </div>
                    <div className="mt-4 md:mt-0 flex space-x-3">
                      <button className="flex items-center px-4 py-2 bg-green-600 hover:bg-green-700 text-white rounded-lg transition-colors">
                        <Check className="w-4 h-4 mr-2" />
                        Accept
                      </button>
                      <button className="flex items-center px-4 py-2 bg-gray-700 hover:bg-gray-600 text-white rounded-lg transition-colors">
                        <X className="w-4 h-4 mr-2" />
                        Ignore
                      </button>
                    </div>
                  </div>
                </motion.div>
              ))}
            </div>
          </motion.div>
        )}

        {/* History Tab */}
        {activeTab === "history" && (
          <motion.div
            variants={itemVariants}
            className="glass-card p-6 rounded-2xl"
          >
            <h2 className="text-2xl font-bold text-white mb-6">
              Donation History
            </h2>
            <div className="overflow-x-auto">
              <table className="w-full">
                <thead>
                  <tr className="border-b border-gray-700">
                    <th className="text-left py-3 text-gray-300">Date</th>
                    <th className="text-left py-3 text-gray-300">Location</th>
                    <th className="text-left py-3 text-gray-300">Volume</th>
                    <th className="text-left py-3 text-gray-300">Status</th>
                  </tr>
                </thead>
                <tbody>
                  {donationHistory.map((donation, index) => (
                    <motion.tr
                      key={donation.id}
                      initial={{ opacity: 0, y: 20 }}
                      animate={{ opacity: 1, y: 0 }}
                      transition={{ delay: index * 0.1 }}
                      className="border-b border-gray-800 hover:bg-white/5 transition-colors"
                    >
                      <td className="py-4">
                        <div className="flex items-center">
                          <Calendar className="w-4 h-4 mr-2 text-gray-400" />
                          <span className="text-white">{donation.date}</span>
                        </div>
                      </td>
                      <td className="py-4">
                        <div className="flex items-center">
                          <MapPin className="w-4 h-4 mr-2 text-gray-400" />
                          <span className="text-white">
                            {donation.location}
                          </span>
                        </div>
                      </td>
                      <td className="py-4">
                        <span className="text-white">{donation.volume}</span>
                      </td>
                      <td className="py-4">
                        <span
                          className={`px-3 py-1 rounded-full text-xs font-medium ${getStatusColor(
                            donation.status
                          )}`}
                        >
                          {donation.status.charAt(0).toUpperCase() +
                            donation.status.slice(1)}
                        </span>
                      </td>
                    </motion.tr>
                  ))}
                </tbody>
              </table>
            </div>
          </motion.div>
        )}
      </motion.main>
    </div>
  );
};

export default DonorDashboard;
